-- Shared curated and member-submitted upkeep resources and private helpfulness votes.
create table public.upkeep_resources (
  id text primary key default gen_random_uuid()::text,
  category text not null check (category in ('strings','woodwinds','brass','percussion','keyboard','voice')),
  level text not null check (level in ('beginner','advanced')),
  topic text not null check (char_length(trim(topic)) between 1 and 120),
  title text not null check (char_length(trim(title)) between 1 and 240),
  publisher text not null check (char_length(trim(publisher)) between 1 and 160),
  scope text not null check (char_length(trim(scope)) between 1 and 160),
  summary text not null check (char_length(trim(summary)) between 1 and 1200),
  url text not null check (char_length(url) <= 2000 and url ~* '^https?://[^/@[:space:]]+([/?#][^[:space:]]*)?$'),
  reviewed_at date,
  user_id uuid references public.users(id) on delete cascade,
  created_at timestamptz not null default now(),
  constraint member_resources_are_not_staff_reviewed check (user_id is null or reviewed_at is null)
);
create index upkeep_resources_category_level on public.upkeep_resources(category, level);
create unique index upkeep_member_resource_url on public.upkeep_resources(category, level, lower(url)) where user_id is not null;
create table public.upkeep_resource_votes (
  resource_id text not null references public.upkeep_resources(id) on delete cascade,
  user_id uuid not null references public.users(id) on delete cascade,
  value smallint not null check (value in (-1, 1)),
  primary key (resource_id, user_id)
);
alter table public.upkeep_resources enable row level security;
alter table public.upkeep_resource_votes enable row level security;
grant select on public.upkeep_resources to anon, authenticated;
grant insert, update, delete on public.upkeep_resources to authenticated;
grant select, insert, update, delete on public.upkeep_resource_votes to authenticated;
revoke all on public.upkeep_resource_votes from anon;
create policy "Resources are public" on public.upkeep_resources for select using (true);
create policy "Members submit their own resources" on public.upkeep_resources for insert to authenticated with check (auth.uid() = user_id and reviewed_at is null);
create policy "Members edit their own resources" on public.upkeep_resources for update to authenticated using (auth.uid() = user_id) with check (auth.uid() = user_id and reviewed_at is null);
create policy "Members remove their own resources" on public.upkeep_resources for delete to authenticated using (auth.uid() = user_id);
create policy "Members read only their own helpfulness votes" on public.upkeep_resource_votes for select to authenticated using (auth.uid() = user_id);
create policy "Members vote on others resources" on public.upkeep_resource_votes for insert to authenticated with check (
  auth.uid() = user_id and exists (select 1 from public.upkeep_resources r where r.id = resource_id and r.user_id is distinct from auth.uid())
);
create policy "Members change their own votes" on public.upkeep_resource_votes for update to authenticated using (auth.uid() = user_id) with check (
  auth.uid() = user_id and exists (select 1 from public.upkeep_resources r where r.id = resource_id and r.user_id is distinct from auth.uid())
);
create policy "Members clear their own votes" on public.upkeep_resource_votes for delete to authenticated using (auth.uid() = user_id);

-- Return ordered public resources without exposing vote totals or other voters.
create function public.list_upkeep_resources(p_category text, p_level text)
returns table(id text, category text, level text, topic text, title text, publisher text, scope text, summary text, url text, reviewed_at date, user_id uuid, author text)
language sql stable security definer set search_path = '' as $$
  select r.id, r.category, r.level, r.topic, r.title, r.publisher, r.scope, r.summary, r.url, r.reviewed_at, r.user_id,
    case when r.user_id is null then null else coalesce(u.display_name, 'Irregular Pearl member') end
  from public.upkeep_resources r
  left join public.users u on u.id = r.user_id
  left join (select v.resource_id, sum(v.value) as score from public.upkeep_resource_votes v group by v.resource_id) tally on tally.resource_id = r.id
  where r.category = p_category and r.level = p_level
  order by coalesce(tally.score, 0) desc, r.created_at asc, r.id asc;
$$;
revoke all on function public.list_upkeep_resources(text, text) from public;
grant execute on function public.list_upkeep_resources(text, text) to anon, authenticated;

